items = []


def add(name, role, axes, milestone, body, exec_class='EXEC-AUTHORIZED'):
    scope = ('Execution class: EXEC-AUTHORIZED — the commands named in this item, and no other.\n'
             if exec_class == 'EXEC-AUTHORIZED' else
             'Execution class: NO-EXEC — read/grep/glob only.\nScope: executed=none\n')
    items.append({'name': name, 'role': role, 'axes': axes, 'milestone': milestone,
                  'prompt': GODSPEED + '\n' + scope + body.strip()})


